create or replace function public.seminar_email_access_v1(p_email text) returns jsonb language sql security invoker set search_path = '' as $$ select case when char_length(lower(btrim(coalesce(p_email,'')))) <= 254 and lower(btrim(coalesce(p_email,''))) ~ '^[^[:space:]@]+@ijr[.]edu[.]co$' then jsonb_build_object('ok',true,'email',lower(btrim(p_email)),'identity_status','institutional_email_lab') else jsonb_build_object('ok',false,'error','institutional_email_required') end; $$;
